fn force_01mob_aco_run(ctx: &Ctx, mut step: Force01mobAcoStep, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            Force01mobAcoStep::Start => {
                step = Force01mobAcoStep::OnEnable;
                continue 'machine;
            }
            Force01mobAcoStep::OnEnable => {
                ctx.call(Function::DoNpcEvent, vec![Val::from("Trocco#aco1::On01_Start")])?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("force_5-1"),
                        Val::from(22),
                        Val::from(29),
                        Val::from("Red Plant"),
                        Val::from(1078),
                        Val::from(1),
                        Val::from("force_01mob#aco::OnMyMobDead"),
                    ],
                )?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("force_5-1"),
                        Val::from(29),
                        Val::from(29),
                        Val::from("Red Plant"),
                        Val::from(1078),
                        Val::from(1),
                        Val::from("force_01mob#aco::OnMyMobDead"),
                    ],
                )?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("force_5-1"),
                        Val::from(29),
                        Val::from(22),
                        Val::from("Red Plant"),
                        Val::from(1078),
                        Val::from(1),
                        Val::from("force_01mob#aco::OnMyMobDead"),
                    ],
                )?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("force_5-1"),
                        Val::from(22),
                        Val::from(22),
                        Val::from("Red Plant"),
                        Val::from(1078),
                        Val::from(1),
                        Val::from("force_01mob#aco::OnMyMobDead"),
                    ],
                )?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("force_5-1"),
                        Val::from(25),
                        Val::from(25),
                        Val::from("Red Plant"),
                        Val::from(1078),
                        Val::from(1),
                        Val::from("force_01mob#aco::OnMyMobDead"),
                    ],
                )?;
                return Err(Stop::End);
            }
            Force01mobAcoStep::OnReset => {
                ctx.call(
                    Function::KillMonster,
                    vec![Val::from("force_5-1"), Val::from("force_01mob#aco::OnMyMobDead")],
                )?;
                return Err(Stop::End);
            }
            Force01mobAcoStep::OnMyMobDead => {
                if ctx
                    .call(
                        Function::MobCount,
                        vec![Val::from("force_5-1"), Val::from("force_01mob#aco::OnMyMobDead")],
                    )?
                    .number()?
                    < 1
                {
                    ctx.call(Function::DoNpcEvent, vec![Val::from("Trocco#aco1::On01_End")])?;
                    ctx.call(Function::DoNpcEvent, vec![Val::from("arena_aco1::OnReset_01")])?;
                }
                return Err(Stop::End);
            }
        }
    }
}

